import{z as i,x as B,o as n,c as d,q as s,j as A,D as E,d as o,s as t,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"正则匹配与回溯爆炸","description":"","frontmatter":{"title":"正则匹配与回溯爆炸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/regex-backtracking.md","filePath":"cs/regex-backtracking.md","lastUpdated":1791063341000}'),p={name:"cs/regex-backtracking.md"};function m(c,a,h,F,D,C){const r=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="正则匹配与回溯爆炸" tabindex="-1">正则匹配与回溯爆炸 <a class="header-anchor" href="#正则匹配与回溯爆炸" aria-label="Permalink to &quot;正则匹配与回溯爆炸&quot;">​</a></h1><div class="epigraph"><p>正则对应 NFA，可线性于文本；回溯实现在嵌套 `*` 上可指数，ReDoS 是算法选择不是语言必然。</p><footer>—— 据 Thompson, Regular Expression Search Algorithm, 1968；Aho, Sethi, Ullman 龙书；[Chomsky](/cs/chomsky-hierarchy) 对照整理</footer></div><p>上一课<a href="/cs/lyndon-duval">Lyndon 分解</a>收束线性串技法。正则匹配在主干词法会再遇。本课缺口是<strong>复杂度</strong>：Thompson NFA 模拟 \\(O(nm)\\)，回溯引擎最坏指数。不重写正则→NFA 全构造。后课平面几何。线性串课序在此结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正则语言可用 NFA，文本长 \\(n\\)、表达式长 \\(m\\)，Thompson 模拟 \\(O(nm)\\)。POSIX/Perl 回溯：每个 <code>*</code> 分叉，<code>a?^n a^n</code> 一类使路径指数。恶意正则 + 文本 = ReDoS。捕获组、回溯引用超出正则，更难。</p><p>缺口是实现模型，不是泵引理。</p><h3 id="不是「正则很慢」" tabindex="-1">不是「正则很慢」 <a class="header-anchor" href="#不是「正则很慢」" aria-label="Permalink to &quot;不是「正则很慢」&quot;">​</a></h3><p>语言类是正则，算法可以是 NFA。慢来自回溯实现。不要把正则语言判成 NPC。</p><p><span class="marginnote">Thompson 1968。Russ Cox 对回溯 vs NFA 的工程论述广泛引用。龙书词法扫描。后课凸包换几何。</span></p><p><span class="marginnote">数字实例：对 <code>(a+)+</code> 匹配 20 个 <code>a</code> 后接 <code>X</code>。回溯引擎在每个 <code>a</code> 上都面临「这层吃还是留给外层吃」的分叉，路径数约 \\(2^{20}\\approx 10^6\\)；文本翻倍到 40 个 <code>a</code>，路径数涨到 \\(2^{40}\\approx 10^{12}\\)——慢上一百万倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要最坏线性：Thompson NFA 或 DFA（DFA 可能 \\(2^m\\) 状态）。需要回溯特性才用回溯，并限制或超时。诊断：嵌套量词 + 长失败文本。</p>',12)),(n(),A(l,null,{default:E(()=>[t(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RE%5B%22%E6%AD%A3%E5%88%99%22%5D%20--%3E%20NFA%5B%22Thompson%20NFA%20O(nm)%22%5D%0A%20%20RE%20--%3E%20BT%5B%22%E5%9B%9E%E6%BA%AF%EF%BC%9A%E6%9C%80%E5%9D%8F%E6%8C%87%E6%95%B0%22%5D%0A%20%20BT%20--%3E%20REDOS%5B%22ReDoS%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[o("DFA 最小化接"),e("a",{href:"/cs/dfa-minimization"},"DFA 最小化"),o("。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[o("NFA 位集或列表模拟：当前位置集合，每字符扫边。回溯是 DFS 这条 NFA，最坏走遍路径。与 CYK：上下文无关才 \\(O(n^3)\\)。与 KMP：单模式无 "),e("code",null,"*"),o("。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：Thompson 模拟就是「把 NFA 所有可能的当前位置收成一个集合，每读一个字符，整组集合一起前进一步」。直觉类比：回溯是派一个人每条岔路都试一遍；Thompson 是每条岔路口各站一个人同时走——步数永远等于文本长度。")],-1)),(n(),A(l,null,{default:E(()=>[t(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20(a%2B)%2B%20%E5%AF%B9%E6%96%87%E6%9C%AC%20aaaaX%22%5D%20--%3E%20S1%5B%22%E5%9B%9E%E6%BA%AF%EF%BC%9A%E7%AC%AC%E4%B8%80%E4%B8%AA%20a%2B%20%E5%90%83%201%20%E4%B8%AA%20a%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%A4%B1%E8%B4%A5%E5%9B%9E%E9%80%80%EF%BC%9A%E6%94%B9%E5%90%83%202%20%E4%B8%AA%20a%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E5%86%8D%E5%9B%9E%E9%80%80%EF%BC%9A%E6%94%B9%E5%90%83%203%20%E4%B8%AA%20a%20%E2%80%A6%E2%80%A6%22%5D%0A%20%20S3%20--%3E%20EXP%5B%22%E8%B7%AF%E5%BE%84%E6%95%B0%E7%BA%A6%202%5En%EF%BC%9A%E6%8C%87%E6%95%B0%E7%88%86%E7%82%B8%22%5D%0A%20%20P%20--%3E%20T%5B%22Thompson%EF%BC%9A%E7%BB%B4%E6%8A%A4%E5%90%8C%E6%97%B6%E6%B4%BB%E7%9A%84%E7%8A%B6%E6%80%81%E9%9B%86%22%5D%0A%20%20T%20--%3E%20SET1%5B%22%E8%AF%BB%E5%AE%8C%20a%20%E5%90%8E%EF%BC%9A%7Bs2%2Cs3%7D%22%5D%0A%20%20SET1%20--%3E%20SET2%5B%22%E5%86%8D%E8%AF%BB%20a%EF%BC%9A%7Bs3%2Cs4%7D%EF%BC%8C%E6%AF%8F%E6%AD%A5%E5%8F%AA%E6%89%AB%E4%B8%80%E9%81%8D%22%5D%0A%20%20SET2%20--%3E%20LIN%5B%22O(n%C2%B7m)%EF%BC%8C%E4%B8%8E%E5%88%86%E5%8F%89%E6%95%B0%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PCRE 全语义。不写递归正则。后课默认：最坏要线性用 NFA；回溯当工程风险。下一课凸包 Graham / Andrew。</p><p><span class="marginnote">常见误区：初学者以为正则慢是「表达式表达力太强」。正则语言类恰好是能线性匹配的那一层，慢的只是回溯实现。给引擎加超时是止血，换 NFA/DFA 引擎才是根治。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正则语言可 \\(O(nm)\\) NFA。</li><li>回溯实现可指数，ReDoS。</li><li>超正则特征另计代价。</li><li>出处：Thompson, 1968；龙书。</li></ul>',5))])}const S=i(p,[["render",m]]);export{u as __pageData,S as default};
